import{_ as r,C as l,o as n,c as t,j as i,E as o,a as e,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/9-sinf-game/"},"n":3,"bob":"II-bob · 2D grafika asoslari va Photoshop","lessons":[{"g":7,"title":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","lead":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","link":"/9-sinf-game/hafta-03/dars-1","slide":"/slaydlar/9-sinf-game/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-1-test.html"},{"g":8,"title":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","lead":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","link":"/9-sinf-game/hafta-03/dars-2","slide":"/slaydlar/9-sinf-game/hafta-03/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-2-test.html"},{"g":9,"title":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","lead":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","link":"/9-sinf-game/hafta-03/dars-3","slide":"/slaydlar/9-sinf-game/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-game/hafta-03/index.md","filePath":"9-sinf-game/hafta-03/index.md"}`),h={name:"9-sinf-game/hafta-03/index.md"},g={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function y(c,a,f,u,v,q){const s=l("Icon");return n(),t("div",null,[i("div",g,[i("h2",m,[o(s,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_7-dars-photoshop-interfeysi-va-vositalari-3-qism-qatlamlar-arxitekturasi-va-assetlar-kollaji" tabindex="-1">7-dars: Photoshop interfeysi va vositalari (3-qism): Qatlamlar arxitekturasi va assetlar kollaji <a class="header-anchor" href="#_7-dars-photoshop-interfeysi-va-vositalari-3-qism-qatlamlar-arxitekturasi-va-assetlar-kollaji" aria-label="Permalink to &quot;7-dars: Photoshop interfeysi va vositalari (3-qism): Qatlamlar arxitekturasi va assetlar kollaji&quot;">​</a></h3><ol><li>Ko&#39;p qatlamli o&#39;yin loyihalarida nima uchun qatlamlarni <code>[01_Background]</code>, <code>[02_Midground]</code>, <code>[03_Foreground]</code>, <code>[04_UI_HUD]</code> guruhlariga (<code>Ctrl + G</code>) ajratish zarurligini tushuntiring.</li><li>Oddiy rastr qatlamni kichraytirib yana kattalashtirgandagi piksel yo&#39;qolishi bilan <strong>Smart Object</strong> himoyasi o&#39;rtasidagi farqni 3 ta jumlada tasvirlang.</li><li>Dumaloq metall qalqonga zang yoki kosmik teksturani bog&#39;lashda <strong>Clipping Mask (<code>Ctrl + Alt + G</code>)</strong> qanday ishlashini amaliy bosqichlarda yozing.</li><li>O&#39;yin obyekti fonda havoda muallaq turgandek ko&#39;rinmasligi uchun <strong>Kontakt soyasi (Contact Shadow)</strong> qaysi rejimda (<code>Multiply</code>) va qanday parametrli cho&#39;tka bilan chiziladi?</li></ol><hr><h3 id="_8-dars-ranglar-nazariyasi-va-dizayn-asoslari-1-qism-rgb-vs-cmyk-rang-g-ildiragi-va-rang-psixologiyasi" tabindex="-1">8-dars: Ranglar nazariyasi va dizayn asoslari (1-qism): RGB vs CMYK, rang g&#39;ildiragi va rang psixologiyasi <a class="header-anchor" href="#_8-dars-ranglar-nazariyasi-va-dizayn-asoslari-1-qism-rgb-vs-cmyk-rang-g-ildiragi-va-rang-psixologiyasi" aria-label="Permalink to &quot;8-dars: Ranglar nazariyasi va dizayn asoslari (1-qism): RGB vs CMYK, rang g&#39;ildiragi va rang psixologiyasi&quot;">​</a></h3><ol><li>Nima sababdan kompyuter va smartfon o&#39;yinlari uchun grafik assetlar faqat <strong>RGB</strong> (additiv) modelida tayyorlanishi shart va nega <strong>CMYK</strong> o&#39;yin dvijoklarida ishlatilmaydi?</li><li>Yoxannes Itten rang g&#39;ildiragidagi 3 ta birlamchi rang (Qizil, Sariq, Ko&#39;k) asosida qaysi 3 ta ikkilamchi ranglar qanday hosil bo&#39;lishini yozing.</li><li>Yashil o&#39;rmon sahnasida harakatlanuvchi qahramon ko&#39;zga darhol tashlanishi uchun <strong>Komplementar kontrast</strong> qoidasi bo&#39;yicha uning libosiga qaysi rang tanlanishi kerak?</li><li>O&#39;yindagi 3 xil sehrli ichimlik (Potion) uchun rang psixologiyasiga muvofiq ranglar tanlang: Jon to&#39;ldiruvchi (Health), Sehr quvvati (Mana) va Chidamlilik (Stamina).</li></ol><hr><h3 id="_9-dars-ranglar-nazariyasi-va-dizayn-asoslari-2-qism-color-picker-swatches-va-gradient-tool" tabindex="-1">9-dars: Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient Tool <a class="header-anchor" href="#_9-dars-ranglar-nazariyasi-va-dizayn-asoslari-2-qism-color-picker-swatches-va-gradient-tool" aria-label="Permalink to &quot;9-dars: Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient Tool&quot;">​</a></h3><ol><li>Dizaynerlar uchun eng qulay bo&#39;lgan <strong>HSB</strong> modelining 3 ta parametri (Hue, Saturation, Brightness) nimani anglatishini va ularning qiymat oraliqlarini ko&#39;rsating.</li><li>O&#39;yin yaratishda nima sababdan tasodifiy ranglar ishlatilmay, <strong>Swatches</strong> panelida 4–6 ta asosiy rangdan iborat rasmiy o&#39;yin palitrasi saqlanishi kerak?</li><li>O&#39;yin sahnasiga quyosh chiqishi osmonini chizish uchun <strong>Linear Gradient</strong>, qahramon atrofidagi aylanma sehrli nurni chizish uchun esa <strong>Radial Gradient</strong> qanday ishlatilishini tushuntiring.</li><li>Katta ekranda silliq gradiyent o&#39;tishi o&#39;rniga pog&#39;onali yoqimsiz chandiqlar (<strong>Color Banding</strong>) paydo bo&#39;lganda, buni bartaraf etish uchun Photoshopda qaysi filtr (Noise) qo&#39;llaniladi?</li></ol><hr>',11))])])}const b=r(h,[["render",y]]);export{p as __pageData,b as default};
